INSERT INTO "Otazky" VALUES ('1', '0', '0', '1', 'Dať prednosť v jazde sa rozumie', NULL, '1', '1', 'povinnosť účastíka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť smer alebo rýchlosť jazdy', 'povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť smer jazdy, môže však zmeniť rýchlosť jazdy', 'povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť rýchlosť jazdy, môže však zmeniť smer jazdy');
